"""Generate the research report and a self-contained local results dashboard."""
from research_common import *
import html,base64,platform,importlib.metadata as metadata

def load(name): return pd.read_csv(TABLES/(name+'.csv'))
def ht(frame): return '<div class="table-wrap">'+frame.to_html(index=False,border=0,float_format=lambda x:f'{x:.5g}')+'</div>'
def md(frame):
 cols=list(frame.columns); lines=['| '+' | '.join(cols)+' |','| '+' | '.join(['---']*len(cols))+' |']
 for _,r in frame.iterrows(): lines.append('| '+' | '.join(f'{v:.5g}' if isinstance(v,float) else str(v) for v in r)+' |')
 return '\n'.join(lines)

def main():
 desc=load('descriptive_statistics'); corr=load('descriptive_correlations'); diag=load('var_diagnostics'); lp=load('local_projections'); inter=load('regime_interactions'); events=load('fomc_regressions'); ec=load('fomc_sample_counts'); metrics=load('forecast_test_metrics'); usd=load('forecast_usd_paired_tests')
 summary=pd.read_csv(ROOT/'data/processed/forecast_sample_summary.csv')
 floor=load('forecast_variance_floor_diagnostics')
 crypto=desc[desc.variable.isin(['btc_usd_log_return','eth_usd_log_return'])][['regime','variable','n','mean','std','q01','q99','excess_kurtosis']]
 crypto_display=crypto.copy()
 for c in ['mean','std','q01','q99']: crypto_display[c]*=100
 crypto_display=crypto_display.rename(columns={c:c+'_pct' for c in ['mean','std','q01','q99']})
 selected=metrics.loc[metrics.groupby(['asset','variant','target']).validation_objective.idxmin()].copy()
 table(selected,'forecast_validation_selected_models')
 significant_inter=inter[inter.qvalue_bh<.05]
 significant_lp=lp[(lp.regime=='full')&(lp.qvalue_bh<.05)]
 event_main=events[(events.coverage=='complete')&(events.regime=='full')&(events.specification=='target_nextmeeting')]
 findings=[]
 v0=lp[(lp.regime=='full')&(lp.shock=='vix_change')&(lp.horizon_sessions==0)].set_index('asset')
 findings.append(f'LP cùng phiên: tăng 5 điểm VIX đi kèm BTC {v0.loc["btc","beta_pct"]:.2f}% và ETH {v0.loc["eth","beta_pct"]:.2f}% cumulative log return sau các controls đã khai báo. Đây là quan hệ đồng thời có điều kiện, không phải tác động nhân quả.')
 for a in ['btc','eth']:
  q=desc[(desc.variable==a+'_usd_log_return')&(desc.regime=='full')].iloc[0]
  findings.append(f'{a.upper()}: {int(q.n):,} daily returns; độ lệch chuẩn {100*q["std"]:.2f}%/ngày; excess kurtosis {q.excess_kurtosis:.2f}. Phân phối có đuôi dày, nên không dùng giả định normal return để diễn giải rủi ro.')
 unstable=diag[~diag.stable.astype(bool)]
 findings.append(f'VAR ổn định ở {int(diag.stable.sum())}/{len(diag)} hệ đã ước lượng. {int((diag.whiteness_p<.05).sum())}/{len(diag)} hệ bác bỏ kiểm định residual whiteness ở mức 5%; cần xem chẩn đoán trước khi diễn giải IRF.')
 findings.append(f'LP toàn mẫu: {len(significant_lp)}/{len(lp[lp.regime=="full"])} hệ số có q-value BH < 0,05. Tương tác giai đoạn/stress: {len(significant_inter)}/{len(inter)} hệ số đạt cùng ngưỡng; chưa có bằng chứng vững về khác biệt theo các kiểm định này. Không đồng nhất việc không bác bỏ với chứng minh không có khác biệt.')
 findings.append(f'Event study baseline có {int(ec[(ec.asset=="BTC")&(ec.regime=="full")&(ec.coverage=="complete")].n_events.iloc[0])} cửa sổ BTC và {int(ec[(ec.asset=="ETH")&(ec.regime=="full")&(ec.coverage=="complete")].n_events.iloc[0])} cửa sổ ETH đầy đủ dữ liệu phút; hồi quy dùng HC3 và kiểm tra chênh lệch pre/post trực tiếp.')
 n_sig=int(((usd.qvalue_bh<.05)&(usd.mean_loss_with_minus_without<0)).sum())
 findings.append(f'Thêm USD: {n_sig}/{len(usd)} phép so sánh loss ghép cặp cho cải thiện với q-value BH < 0,05. Xem từng asset/target/model; không suy rộng từ một cấu hình sang toàn bộ nghiên cứu.')
 findings.append('Các cấu hình boosting variance có dự báo chạm sàn 1e-12, làm QLIKE nhạy mạnh; không dùng chênh lệch QLIKE của chúng làm bằng chứng chắc chắn về USD. Baseline không được thay đổi sau khi xem test.')
 sections=[]
 def section(title,body): sections.append((title,body))
 section('1. Câu hỏi và phạm vi', '<p>Đo quan hệ giữa biến động điều kiện tài chính toàn cầu và BTC/ETH; kiểm tra khác biệt pre/post-2020, stress và phản ứng quanh FOMC; đánh giá giá trị dự báo bổ sung của USD. Baseline không MOVE. Snapshot gốc tải 16/10/2026, quan sát đến 15/10/2026; không refresh nguồn trong lần chạy nghiên cứu này.</p><p>Đây là bản nghiên cứu tái lập đầu tiên, chưa phải bằng chứng xác lập nhân quả. Những hạn chế dữ liệu đã biết được giữ lại và công khai.</p>')
 section('2. Phát hiện chính', '<ul>'+''.join('<li>'+html.escape(x)+'</li>' for x in findings)+'</ul>')
 section('3. Dữ liệu và EDA','<p>Panel lịch sử có 4.671 ngày. ETH bắt đầu ngắn hơn BTC. Đơn vị dưới đây: mean/std/quantiles theo phần trăm log return. Không winsorize hoặc bỏ return cực trị. Chỉ số oil WTI âm được giữ; log return không xác định để thiếu.</p>'+ht(crypto_display)+'<img src="figures/eda_history.png" alt="Crypto history and financial conditions"><img src="figures/eda_returns_volatility.png" alt="Return tails and volatility"><img src="figures/eda_correlations.png" alt="Descriptive correlations"><p>Tương quan là pairwise, số quan sát khác nhau và thời gian đóng cửa Mỹ khác UTC close crypto; không diễn giải là tác động. Sáu mức giá S&P lệch nguồn và return phiên kế tiếp được kiểm tra riêng.</p>'+ht(load('sp500_discrepancy_sensitivity')))
 section('4. VAR và nhận diện','<p>Mỗi tài sản có hệ VAR riêng: ΔVIX, USD log return, Δ2Y, Δ10Y, crypto log return. Tất cả giá được lấy tại các ngày đủ quan sát chung, sau đó mới tính chênh lệch/return giữa hai ngày đó. Crypto vì vậy bao gồm cuối tuần/ngày lễ nằm giữa các phiên. Một horizon là một phiên đủ dữ liệu, không phải một ngày lịch.</p><p>Độ trễ BIC trong 1–10; AIC và đảo thứ tự các biến macro là robustness. IRF baseline dùng Cholesky, macro đứng trước crypto. Thứ tự này là giả định nhận diện; thay đổi VIX/USD/yield không mặc nhiên là shock ngoại sinh. Khoảng tin cậy VAR là pointwise asymptotic 95%, có giới hạn khi residual không trắng hoặc có đuôi dày.</p>'+ht(diag)+'<p><strong>Whiteness bị bác bỏ ở cả baseline và đặc tả AIC đã xét. Các VAR IRFs hiện tại chỉ là kết quả thăm dò; không dùng độ ổn định của hệ để khẳng định đặc tả đã đạt. Chưa mở rộng đặc tả ngoài kế hoạch để tìm một mô hình đạt kiểm định.</strong></p>'+ht(load('var_robustness_diagnostics'))+'<p>ADF có giả thuyết gốc unit root; KPSS có giả thuyết gốc stationarity. P-value KPSS ở biên bảng được ghi như biên, không phải giá trị chính xác. Xem bảng stationarity_tests.csv và toàn bộ VAR IRFs/robustness trong thư mục tables.</p>')
 lp_display=lp[(lp.regime=='full')&lp.horizon_sessions.isin([0,5,20])][['asset','shock','horizon_sessions','beta_pct','lower95','upper95','pvalue','qvalue_bh','nobs']]
 section('5. Local Projections, giai đoạn và stress','<p>LP ước lượng cumulative crypto log return từ t đến t+h, h = 0,1,2,5,10,20,30 phiên. Controls gồm các thay đổi macro cùng phiên và 5 lags của toàn hệ. HAC maxlags=max(5,h+1); intervals 95% pointwise. Hệ số phản ánh quan hệ có điều kiện và có thể đồng thời: không gọi là causal monetary shock.</p><p>Quy mô: +5 điểm VIX, +1% USD log return, +10 bps yield. Stress được định nghĩa trước bằng VIX phiên trước >30. Chênh lệch pre/post và stress được kiểm định bằng hồi quy pooled có interaction, không dựa vào việc hai CI có chồng nhau. Điều chỉnh BH cho họ hệ số LP và họ interaction; không phải simultaneous confidence bands.</p><img src="figures/lp_responses.png" alt="Local projection responses">'+ht(lp_display)+'<img src="figures/rolling_sensitivity.png" alt="Rolling 252-session sensitivity"><p>Rolling window 252 phiên, cập nhật mỗi 21 phiên; đây là mô tả lịch sử, không dùng để chọn feature/hyperparameter forecasting.</p>')
 section('6. Event study FOMC','<p>Statement windows [-10,+20] phút, đổi giờ Eastern sang UTC có DST. Return và realized variance cửa sổ tính từ Coinbase minute candles, khác nguồn giá tổng hợp Coin Metrics daily. Baseline chỉ dùng cửa sổ đủ minute candles; robustness thêm endpoint-only.</p><p>Hồi quy đồng thời MP1 và MP2, hệ số theo shock 10 bps; HC3 standard errors. Alternative surprise là STMT do SF Fed công bố. MPS PCA là thước đo hồi cứu cho event study, không đưa vào forecast real time. Policy information effect và tin tức trùng thời điểm có thể còn tồn tại.</p>'+ht(ec[ec.coverage=='complete'])+'<img src="figures/fomc_scatter.png" alt="FOMC statement responses">'+ht(event_main[['asset','term','beta_return_pct','lower95','upper95','pvalue','qvalue_bh','nobs']]))
 section('7. Thiết kế forecasting','<p>Target là next UTC-day return hoặc squared return, không phải next eligible row. Dòng cuối có target thiếu không sử dụng. Squared return là proxy nhiễu cho variance, không phải daily intraday realized volatility. Không fill 0/interpolate market returns; dùng complete-case origins theo feature đã chốt.</p>'+ht(summary[['asset','configuration','first_origin_date','last_origin_date','n_rows','train_rows','validation_rows','test_rows']])+'<p>Train trước 2023; validation 2023–2024; test từ 2025, tính theo ngày target. Kiểm tra nhãn cuối training/development đã đóng trước origin đầu validation/test. Chuẩn hóa X/y chỉ fit trong training khi tuning. Chọn tham số bằng validation MSE cho return và QLIKE cho squared return; sau đó refit train+validation một lần, giữ tham số cố định trong test. Features cập nhật tại từng origin theo dữ liệu quá khứ.</p><p>Benchmark: historical mean; zero-return hoặc trailing30 variance. Mô hình tuyến tính: Elastic Net; ML: histogram gradient boosting với early stopping tắt để tránh chia validation ngẫu nhiên. Seed 9. Không chọn model theo test; bảng tiếp theo chọn dòng dựa trên validation objective, kể cả benchmark.</p>')
 section('8. Kết quả ngoài mẫu và giá trị USD',ht(selected[['asset','variant','target','model','n_test','rmse','mae','validation_objective']])+'<img src="figures/forecast_usd_comparison.png" alt="Matched USD forecast comparison">'+ht(usd)+'<p>RMSE improvement dương nghĩa là thêm USD giảm RMSE. Paired loss difference âm nghĩa là thêm USD giảm loss: squared error cho return, QLIKE cho variance. QLIKE=mean(log(v_hat)+r_next²/v_hat), thấp hơn tốt hơn; floor v_hat=1e-12 cố định trước đánh giá. Kiểm định HAC lag5/BH là chẩn đoán xấp xỉ, đặc biệt với mô hình nested và origin không đều. Không so trực tiếp mẫu dài không USD với mẫu ngắn có USD để kết luận lợi ích USD.</p>')
 section('8a. Chẩn đoán sàn variance và forecast bằng nhau','<p>Boosting squared-error không đảm bảo dự báo variance dương. Quy tắc chặn cố định tại 1e-12 đã dùng ngay từ validation, không chọn theo test. Khi chạm sàn, loss QLIKE có thể rất lớn; RMSE tốt hơn không đồng nghĩa variance forecast đạt chất lượng. Không tự đổi sang log-target, positive-link loss hoặc tăng floor sau khi thấy test. Nếu cần các mở rộng này sẽ trao đổi trước.</p>'+ht(floor[floor.model=='gradient_boosting'])+'<p>Elastic Net trong cặp common có dự báo test bằng nhau khi thêm USD theo mức shrinkage đã chọn bằng validation. Kết quả này không chứng minh USD không có vai trò kinh tế. Benchmark historical mean và trailing variance vốn không dùng USD, nên không có thay đổi dự báo là đúng thiết kế.</p>')
 section('9. Giới hạn và kết luận sử dụng','<ul><li>Macro PIT dùng ALFRED date-level vintages; không có giờ thực tế của từng update. Quy tắc nhận thông tin tại cuối ngày UTC bảo thủ nhưng không thay cho timestamped delivery archive.</li><li>USD PIT hiện tại chỉ từ 2019; common pre-2020 chỉ có 229 quan sát. Không dùng backcast trước 2019 như thông tin từng biết lúc đó.</li><li>VIX/S&P/gold lag1 là historical-feed proxies; crypto PriceUSD là lịch sử hiện tại. Toàn pipeline không được chứng nhận tuyệt đối không look-ahead.</li><li>Gold là futures GC=F có roll; WTI có giá âm; NFCI là tuần có revision. MOVE được loại theo thiết kế.</li><li>Ngày origin forecasting không liên tục; mô hình phiên và mô hình next-day UTC trả lời các horizon khác nhau.</li><li>Không có kết quả thống kê nào tự biến innovation VAR thành causal policy shock. Kết luận phải dựa trên identification, robustness và uncertainty.</li></ul><p>Kết quả phù hợp cho báo cáo học thuật và kiểm tra giả thuyết. Những trường hợp kiểm định không đạt và kết quả không có ý nghĩa được giữ trong bảng, không loại để làm mạnh câu chuyện.</p>')
 section('10. Tái lập và nguồn','<p>Chạy <code>py -3.11 run_research.py</code> sau khi cài <code>requirements-research.txt</code>. Không cần tải lại dữ liệu. Toàn bộ bảng số, hyperparameter search, dự báo từng origin và diagnostics nằm trong <code>tables/</code>; notebook EDA nằm trong <code>notebooks/01_eda.ipynb</code> ở gốc dự án. Dashboard cục bộ: <a href="dashboard/index.html">mở bảng kết quả tương tác</a>.</p><p>Nguồn dữ liệu: <a href="https://docs.coinmetrics.io/api/v4/">Coin Metrics</a>; <a href="https://alfred.stlouisfed.org/help">ALFRED/FRED</a>; <a href="https://www.frbsf.org/research-and-insights/data-and-indicators/us-monetary-policy-event-study-database/">SF Fed USMPD</a>; <a href="https://finance.yahoo.com/">Yahoo Finance</a>; <a href="https://docs.cdp.coinbase.com/api-reference/exchange-api/rest-api/products/get-product-candles">Coinbase</a>. USMPD: Acosta et al. (2025), SF Fed Working Paper 2025-30. Phương pháp triển khai: <a href="https://www.statsmodels.org/stable/vector_ar.html">statsmodels VAR</a>, <a href="https://www.statsmodels.org/stable/generated/statsmodels.regression.linear_model.RegressionResults.get_robustcov_results.html">robust covariance</a>, <a href="https://scikit-learn.org/stable/modules/cross_validation.html#time-series-split">time-ordered validation</a>. URL và hash nguồn nằm trong bộ dữ liệu gốc.</p>')
 css='''body{font:16px/1.65 system-ui,sans-serif;color:#203247;background:#f3f6fa;margin:0}main{max-width:1180px;margin:auto;background:white;padding:48px}header{border-bottom:4px solid #096b93;padding-bottom:24px}h1{font-size:34px;line-height:1.2}h2{margin-top:44px;color:#095d82}p,li{max-width:1050px}.table-wrap{overflow-x:auto;margin:22px 0}table{border-collapse:collapse;font-size:12px;white-space:nowrap}th,td{text-align:right;padding:9px;border-bottom:1px solid #dfe5ed}th{background:#e9f2f7}td:first-child,th:first-child{text-align:left}img{display:block;max-width:100%;height:auto;margin:24px auto}a{color:#096b93}code{background:#eef2f5;padding:2px 5px}@media(max-width:700px){main{padding:20px}h1{font-size:27px}}@media print{body{background:white}main{padding:0}h2{break-after:avoid}img{break-inside:avoid}}'''
 doc='<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Chủ đề 9 — Báo cáo nghiên cứu</title><style>'+css+'</style><main><header><p>CRYPTO FINANCE LAB · CHỦ ĐỀ 9</p><h1>Global Financial Conditions<br>và thị trường BTC/ETH</h1><p>Baseline không MOVE · Phân tích lịch sử và forecasting tách riêng · Dữ liệu đến 15/10/2026</p></header>'+''.join('<section><h2>'+t+'</h2>'+b+'</section>' for t,b in sections)+'</main></html>'
 (RESULTS/'report.html').write_text(doc,encoding='utf-8')
 # A portable text overview points to full HTML/tables rather than duplicating hundreds of rows.
 text='# Chủ đề 9: Báo cáo nghiên cứu\n\nSnapshot 16/10/2026, dữ liệu đến 15/10/2026. Baseline không MOVE.\n\n## Phát hiện chính\n\n'+'\n'.join('- '+s for s in findings)+'\n\n## Thống kê crypto\n\n'+md(crypto_display)+'\n\n## VAR diagnostics\n\n'+md(diag)+'\n\n## Forecast USD: cùng mẫu\n\n'+md(usd)+'\n\nBáo cáo đầy đủ: [report.html](report.html). Dashboard: [dashboard/index.html](dashboard/index.html). Các phát hiện là quan hệ có điều kiện, không mặc nhiên là tác động nhân quả. Forecasting vẫn có giới hạn historical market-feed proxies.\n'
 (RESULTS/'report.md').write_text(text,encoding='utf-8')
 versions={p:metadata.version(p) for p in ['numpy','pandas','scipy','matplotlib','statsmodels','scikit-learn','nbformat']}
 js({'python':platform.python_version(),'packages':versions},'environment')
 dashboard(lp,load('var_impulse_responses'),usd,metrics,findings)
 print('\n'.join(findings),flush=True)

def dashboard(lp,var,usd,metrics,findings):
 directory=RESULTS/'dashboard'; directory.mkdir(exist_ok=True)
 payload={'lp':json.loads(lp.to_json(orient='records')),'var':json.loads(var[var.specification=='bic_baseline'].to_json(orient='records')),'usd':json.loads(usd.to_json(orient='records')),'metrics':json.loads(metrics.to_json(orient='records')),'findings':findings}
 template='''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Macro–Crypto Research</title><style>
*{box-sizing:border-box}body{font:15px/1.55 system-ui,sans-serif;background:#f0f4f8;color:#183149;margin:0}.hero{background:#102e45;color:#fff;padding:38px max(5vw,20px)}h1{font-size:32px;margin:8px 0}.eyebrow{letter-spacing:2px;color:#81c5dc;font-size:12px}.hero p{color:#c5dbe7;max-width:900px}.wrap{max-width:1250px;padding:26px;margin:auto}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:24px}.card,.panel{background:white;border:1px solid #dce5ec;border-radius:12px;padding:22px}.card b{font-size:28px;display:block;color:#086b91}.card span{color:#62788b}.controls{display:flex;flex-wrap:wrap;gap:16px;margin-bottom:20px}label{display:flex;flex-direction:column;font-size:12px;color:#526a7d;gap:5px}select{padding:10px 12px;background:white;border:1px solid #bdcedb;border-radius:6px;color:#17394f;font-size:14px}h2{font-size:20px;margin:0 0 16px}.grid{display:grid;grid-template-columns:2fr 1fr;gap:20px}.note{background:#edf5f9;padding:14px;border-left:3px solid #0c7394;font-size:13px}svg{width:100%;height:auto}#point{font-size:28px;color:#096b93}a{color:#087394}.table{overflow:auto}table{border-collapse:collapse;font-size:13px;width:100%;white-space:nowrap}th,td{text-align:right;padding:10px;border-bottom:1px solid #e6edf2}td:first-child,th:first-child{text-align:left}.footer{font-size:12px;color:#607789;padding:24px 0}.badge{display:inline-block;padding:4px 10px;border:1px solid #46738b;border-radius:20px;font-size:12px}@media(max-width:760px){.stats,.grid{grid-template-columns:1fr}.wrap{padding:16px}h1{font-size:25px}.hero{padding:26px 20px}}
</style></head><body><header class="hero"><div class="eyebrow">CRYPTO FINANCE LAB / RESEARCH 09</div><h1>Điều kiện tài chính toàn cầu → BTC / ETH</h1><p>Khám phá kết quả truyền dẫn theo phiên và giá trị dự báo bổ sung của USD. Baseline không MOVE; snapshot dữ liệu đến 15/10/2026.</p><span class="badge">Kết quả nghiên cứu có điều kiện · Không mặc định nhân quả</span></header><main class="wrap"><section class="stats"><div class="card"><b>4.671</b><span>ngày trong panel lịch sử</span></div><div class="card"><b>1.929</b><span>origin mỗi cấu hình common 2019+</span></div><div class="card"><b>448</b><span>origin test mỗi tài sản / cấu hình</span></div></section><section class="panel"><h2>Phản ứng crypto theo điều kiện tài chính</h2><div class="controls"><label>Tài sản<select id="asset"><option value="btc">Bitcoin</option><option value="eth">Ethereum</option></select></label><label>Phương pháp<select id="method"><option value="lp">Local Projections</option><option value="var">VAR / Cholesky</option></select></label><label>Giai đoạn<select id="regime"><option value="full">Toàn mẫu</option><option value="pre2020">Trước 2020</option><option value="post2020">Từ 2020</option></select></label><label>Thay đổi / innovation<select id="shock"><option value="vix_change">VIX +5 điểm</option><option value="usd_return_pct">Broad USD +1%</option><option value="us2y_change_bps">US 2Y +10 bps</option><option value="us10y_change_bps">US 10Y +10 bps</option></select></label><label>Horizon (phiên)<select id="horizon"></select></label></div><div class="grid"><div><svg id="chart" viewBox="0 0 700 320" role="img" aria-label="Phản ứng và khoảng tin cậy 95 phần trăm"></svg><p class="note" id="methodNote"></p></div><div class="card"><span>Ước lượng tại horizon chọn</span><div id="point"></div><p id="interval"></p><p id="inference"></p><p>Một bước = một phiên có đủ dữ liệu Mỹ. Return crypto được gộp qua cuối tuần/ngày lễ giữa hai phiên.</p></div></div></section><section class="panel" style="margin-top:22px"><h2>USD có cải thiện forecasting không?</h2><p>So sánh trên cùng ngày, cùng target, cùng lịch training. Số dương dưới đây nghĩa là RMSE giảm khi thêm USD; q-value là BH-adjusted paired loss test, không phải kiểm định trực tiếp của RMSE.</p><div class="controls"><label>Target<select id="target"><option value="return">Next UTC-day return</option><option value="squared_return">Next UTC-day squared return</option></select></label></div><div id="forecastTable" class="table"></div><p class="note">Train trước 2023; validation 2023–2024; test từ 2025. Squared return là proxy variance. Macro dùng ALFRED vintage; historical market-feed proxies vẫn là giới hạn point-in-time.</p></section><section class="panel" style="margin-top:22px"><h2>Phát hiện và giới hạn</h2><ul id="findings"></ul><a href="../report.html">Đọc báo cáo đầy đủ và phương pháp</a> · <a href="../tables/forecast_test_metrics.csv" download>Tải bảng metrics</a> · <a href="../tables/local_projections.csv" download>Tải LP</a></section><footer class="footer">Nguồn: Coin Metrics, FRED/ALFRED, SF Fed USMPD, Yahoo Finance, Coinbase. Toàn bộ kết quả lấy từ lần chạy đã lưu; dashboard không tự ước lượng lại mô hình.</footer></main><script>const DATA=__PAYLOAD__;
const el=id=>document.getElementById(id);const fmt=x=>Number(x).toFixed(3);let rows=[];
function refresh(reset=false){const method=el('method').value;rows=DATA[method].filter(r=>r.asset===el('asset').value&&r.regime===el('regime').value&&r.shock===el('shock').value).sort((a,b)=>a.horizon_sessions-b.horizon_sessions);const old=Number(el('horizon').value||0);el('horizon').innerHTML=rows.map(r=>`<option value="${r.horizon_sessions}">${r.horizon_sessions}</option>`).join('');el('horizon').value=rows.some(r=>r.horizon_sessions===old)?old:0;draw();}
function draw(){const lp=el('method').value==='lp';let y=rows.map(r=>lp?r.beta_pct:r.response_pct),lo=rows.map(r=>r.lower95),hi=rows.map(r=>r.upper95);let ymin=Math.min(0,...lo),ymax=Math.max(0,...hi);let pad=(ymax-ymin)*.12||1;ymin-=pad;ymax+=pad;const X=x=>65+x/30*605,Y=y=>265-(y-ymin)/(ymax-ymin)*235;let svg='';for(let i=0;i<5;i++){const v=ymin+(ymax-ymin)*i/4;svg+=`<line x1="65" x2="670" y1="${Y(v)}" y2="${Y(v)}" stroke="#e4ecf2"/><text x="58" y="${Y(v)+4}" text-anchor="end" font-size="11" fill="#5e7487">${fmt(v)}</text>`;}svg+=`<line x1="65" x2="670" y1="${Y(0)}" y2="${Y(0)}" stroke="#849aaa"/>`;const line=rows.map((r,i)=>`${X(r.horizon_sessions)},${Y(y[i])}`).join(' ');const band=rows.map((r,i)=>`${X(r.horizon_sessions)},${Y(lo[i])}`).concat(rows.slice().reverse().map((r,j)=>`${X(r.horizon_sessions)},${Y(hi[rows.length-1-j])}`)).join(' ');svg+=`<polygon points="${band}" fill="#1480a5" opacity=".14"/><polyline points="${line}" fill="none" stroke="#096b93" stroke-width="2.5"/>`;for(let h of [0,5,10,20,30])svg+=`<text x="${X(h)}" y="287" text-anchor="middle" font-size="11" fill="#5e7487">${h}</text>`;svg+='<text x="360" y="312" text-anchor="middle" font-size="12">Horizon: eligible US sessions</text><text x="65" y="17" font-size="12">Log return (%)</text>';const idx=rows.findIndex(r=>r.horizon_sessions===Number(el('horizon').value));const r=rows[idx];svg+=`<circle cx="${X(r.horizon_sessions)}" cy="${Y(y[idx])}" r="5" fill="#e79636"/>`;el('chart').innerHTML=svg;el('point').textContent=fmt(y[idx])+'%';el('interval').textContent=`95% pointwise CI: [${fmt(r.lower95)}%, ${fmt(r.upper95)}%]`;el('inference').textContent=lp?`BH q-value: ${fmt(r.qvalue_bh)} · n=${r.nobs}`:'Asymptotic VAR interval; xem stability/whiteness diagnostics trong báo cáo.';el('methodNote').textContent=lp?'LP: cumulative response t..t+h, controls cùng phiên và 5 lags, HAC intervals. Quan hệ có điều kiện, có thể đồng thời.':'VAR: response của riêng horizon h, thứ tự macro-first Cholesky. Khác định nghĩa outcome LP. Thứ tự là giả định; không xác lập causal shock.';}
function forecasts(){const q=DATA.usd.filter(r=>r.target===el('target').value&&r.model!=='historical_mean');el('forecastTable').innerHTML='<table><thead><tr><th>Tài sản / mô hình</th><th>RMSE không USD</th><th>RMSE có USD</th><th>Cải thiện (%)</th><th>q-value</th></tr></thead><tbody>'+q.map(r=>`<tr><td>${r.asset.toUpperCase()} / ${r.model.replaceAll('_',' ')}</td><td>${Number(r.rmse_without).toPrecision(4)}</td><td>${Number(r.rmse_with).toPrecision(4)}</td><td>${Number(r.rmse_improvement_pct).toFixed(2)}</td><td>${fmt(r.qvalue_bh)}</td></tr>`).join('')+'</tbody></table>';}
for(const id of ['asset','method','regime','shock'])el(id).addEventListener('change',()=>refresh());el('horizon').addEventListener('change',draw);el('target').addEventListener('change',forecasts);for(const text of DATA.findings){const li=document.createElement('li');li.textContent=text;el('findings').appendChild(li);}refresh();forecasts();</script></body></html>'''
 (directory/'index.html').write_text(template.replace('__PAYLOAD__',json.dumps(payload,ensure_ascii=False).replace('</','<\\/')),encoding='utf-8')
 # Static smoke checks for the self-contained dashboard contract.
 output=(directory/'index.html').read_text(encoding='utf-8')
 assert '__PAYLOAD__' not in output and 'fetch(' not in output
 assert len(payload['lp']) and len(payload['usd']) and all((FIGURES/f).exists() for f in ['eda_history.png','lp_responses.png','fomc_scatter.png','forecast_usd_comparison.png'])

if __name__=='__main__': main()
